$$$TRACE("Inside "_..%ConfigName_" Method UpdateTacticalDbResultsJdbcCardiologyRequest")
set pResponse = ##class(EnsLib.SQL.Snapshot).%New()

set tSQL = "UPDATE CARDIORISINTERFACE.CARDIO_RESULT SET EGATE_RETRIEVED_DTS=TO_DATE("_pRequest.date_",'YYYYMMDD') WHERE ACCESSION_NO='"_pRequest.accessionNumber_"'"
//set tSQL = "UPDATE CARDIORISINTERFACE.CARDIO_RESULT SET EGATE_RETRIEVED_DTS='"_pRequest.date_"' WHERE ACCESSION_NO='"_pRequest.accessionNumber_"'"
set tSC = ..Adapter.ExecuteUpdate(.noOfRows,tSQL)
$$$TRACE("Status :"_tSC)

if tSC = 1{
	$$$TRACE("Successfully updated the Query:"_tSQL)	
	set pResponse = noOfRows		
}else{
	$$$TRACE("Failed to update the Query:"_tSQL)	
}

Quit tSC

$$$TRACE("Inside "_..%ConfigName_" Method SelectTacticalDbResultsJdbcCardiologyRequest")

set pResponse = ##class(EnsLib.SQL.Snapshot).%New()

set tSQL = "SELECT * FROM CARDIORISINTERFACE.CARDIO_RESULT where STUDY_ID is not null and EGATE_RETRIEVED_DTS is null ORDER BY STUDY_ID ASC"

//set tSQL = "SELECT * FROM CARDIORISINTERFACE.CARDIO_RESULT where empi=551569805"


set tSC = ..Adapter.ExecuteQuery(.pResponse,tSQL)

if tSC = 1{
	$$$TRACE("Successfully executed Query:"_tSQL)
	set rowCount = pResponse.RowCount
	$$$TRACE("Row Count:"_rowCount)		
}else{
	$$$TRACE("Failed to execute Query:"_tSQL)	
}

Quit tSC
